// Process manual keyword input
// El webhook envía los datos en el objeto 'body'
const inputData = $input.first().json;
const webhookBody = inputData.body || inputData;

const keywords = webhookBody.keywords || [];
const clusterName = webhookBody.cluster_name || 'Manual Import';
const projectName = webhookBody.project_name || null;
const source = 'manual';

// Transform keywords into database format
const processedKeywords = keywords.map(keyword => {
  if (typeof keyword === 'string') {
    // Simple string format
    return {
      keyword: keyword,
      search_volume: 0,
      competition: 'Unknown',
      search_intent: 'informacional',
      cluster_name: clusterName,
      project_name: projectName,
      source: source
    };
  } else {
    // Object with metadata
    return {
      keyword: keyword.keyword || '',
      search_volume: keyword.search_volume || 0,
      competition: keyword.competition || 'Unknown',
      search_intent: keyword.intent || keyword.search_intent || 'informacional',
      cluster_name: clusterName,
      project_name: projectName,
      source: source
    };
  }
});

return processedKeywords.map(k => ({json: k}));
